window.docContents[191].resolve({"/Development-Server/#serve-redirects":{"contents":"Redirect rules are matched against the request path by prefix, in order, and the first match wins.\nThe path beneath the matched prefix is appended to the target.\n\n[[redirects]]\nfrom = \"/old\"\nto = \"/new\"\nstatus = 301\n\n[[redirects]]\nfrom = \"/legacy\"\nto = \"/current\"\nstatus = 302\n\n\n","context":"Writing Documentation in Lean with Verso\u0009Development Server\u0009Configuration File","header":"9.3.2. Redirects","id":"/Development-Server/#serve-redirects"}});